using System;using System.Linq;using Mono.Cecil;using Mono.Cecil.Cil;
// Cache material identity only across Fill calls in one panel LateUpdate.
// Geometry and onChange run before this phase. No cache survives the call.
class OptimizeFill {
 static void Need(bool b,string s){if(!b)throw new Exception(s);}
 static MethodReference Bind(MethodReference source,TypeReference owner){var r=new MethodReference(source.Name,source.ReturnType,owner){HasThis=source.HasThis,ExplicitThis=source.ExplicitThis,CallingConvention=source.CallingConvention};foreach(var p in source.Parameters)r.Parameters.Add(new ParameterDefinition(p.ParameterType));return r;}
 static void Main(string[] a){var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(a[2]);var asm=AssemblyDefinition.ReadAssembly(a[0],new ReaderParameters{AssemblyResolver=resolver});var mod=asm.MainModule;var all=mod.Types.SelectMany(t=>t.Methods).Where(m=>m.HasBody).ToArray();var refs=all.SelectMany(m=>m.Body.Instructions).Select(i=>i.Operand as MethodReference).Where(m=>m!=null).ToArray();var panel=mod.GetType("UIPanel");var fill=panel.Methods.Single(m=>m.Name=="Fill");var update=panel.Methods.Single(m=>m.Name=="LateUpdate");Need(fill.IsPrivate&&fill.Parameters.Count==1&&fill.Parameters[0].ParameterType.FullName=="UnityEngine.Material","Original Fill signature");var sites=all.SelectMany(m=>m.Body.Instructions.Select(i=>new{Method=m,Instruction=i})).Where(x=>x.Instruction.Operand is MethodReference&&((MethodReference)x.Instruction.Operand).FullName==fill.FullName).ToArray();Need(sites.Length==1&&sites[0].Method==update,"Only LateUpdate may call Fill");var get=fill.Body.Instructions.Single(i=>i.Operand is MethodReference&&((MethodReference)i.Operand).FullName=="UnityEngine.Material UIWidget::get_material()");var getter=(MethodReference)get.Operand;
 var open=((GenericInstanceType)mod.GetType("InputManager").Fields.Single(f=>f.Name=="guiToKeyNameMapping").FieldType).ElementType;var dict=new GenericInstanceType(open);dict.GenericArguments.Add(mod.GetType("UIWidget"));dict.GenericArguments.Add(fill.Parameters[0].ParameterType);
 Func<string,MethodReference> dm=n=>Bind(refs.First(m=>m.Name==n&&m.DeclaringType is GenericInstanceType&&((GenericInstanceType)m.DeclaringType).ElementType.FullName=="System.Collections.Generic.Dictionary`2"&&(n!=".ctor"||m.Parameters.Count==0)),dict);var ctor=dm(".ctor");var add=dm("Add");var tryGet=dm("TryGetValue");
 var cache=new VariableDefinition(dict);update.Body.Variables.Add(cache);update.Body.InitLocals=true;var ui=update.Body.GetILProcessor();var call=sites[0].Instruction;var pass=ui.Create(OpCodes.Ldloc,cache);foreach(var i in new[]{ui.Create(OpCodes.Ldloc,cache),ui.Create(OpCodes.Brtrue,pass),ui.Create(OpCodes.Newobj,ctor),ui.Create(OpCodes.Stloc,cache),pass})ui.InsertBefore(call,i);
 fill.Parameters.Add(new ParameterDefinition("materials",ParameterAttributes.None,dict));call.Operand=fill;
 var widget=new VariableDefinition(mod.GetType("UIWidget"));var mat=new VariableDefinition(fill.Parameters[0].ParameterType);fill.Body.Variables.Add(widget);fill.Body.Variables.Add(mat);fill.Body.InitLocals=true;var il=fill.Body.GetILProcessor();get.OpCode=OpCodes.Stloc;get.Operand=widget;var done=il.Create(OpCodes.Ldloc,mat);Instruction at=get;foreach(var i in new[]{il.Create(OpCodes.Ldarg_2),il.Create(OpCodes.Ldloc,widget),il.Create(OpCodes.Ldloca,mat),il.Create(OpCodes.Callvirt,tryGet),il.Create(OpCodes.Brtrue,done),il.Create(OpCodes.Ldloc,widget),il.Create(OpCodes.Callvirt,getter),il.Create(OpCodes.Stloc,mat),il.Create(OpCodes.Ldarg_2),il.Create(OpCodes.Ldloc,widget),il.Create(OpCodes.Ldloc,mat),il.Create(OpCodes.Callvirt,add),done}){il.InsertAfter(at,i);at=i;}
 var ops=typeof(OpCodes).GetFields().Where(f=>f.FieldType==typeof(OpCode)).Select(f=>(OpCode)f.GetValue(null)).ToDictionary(o=>o.Name);foreach(var m in new[]{fill,update})foreach(var i in m.Body.Instructions)if(i.OpCode.OperandType==OperandType.ShortInlineBrTarget)i.OpCode=ops[i.OpCode.Name.Substring(0,i.OpCode.Name.Length-2)];asm.Write(a[1]);Console.WriteLine("Only UIPanel.LateUpdate and private Fill changed; one lazy local material map per LateUpdate, no new type/assembly/field");}
}
